import type { Document as EvidenceDocument } from '../services/documentService';

export interface DocumentHotspotRow {
  id: string;
  name: string;
  co2: number;
  category: string;
  vendor: string;
  date: string;
}

export interface DocumentAssessmentAggregate {
  totalCo2: number;
  scope1: number;
  scope2: number;
  scope3: number;
  hotspots: DocumentHotspotRow[];
  companyRows: { label: string; totalKg: number }[];
  productRows: { productName: string; quantity: number; unit: string; allocatedKg: number }[];
  documentCount: number;
}

const toSafeNumber = (value: unknown): number => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
};

/** When transactions lack scope splits, infer ISO 14064 / GHG Protocol-style buckets from spend category text. */
const inferScopesFromCategory = (category: string, total: number): { scope1: number; scope2: number; scope3: number } => {
  const c = (category || '').toLowerCase();
  const t = Math.max(0, total);
  if (!t) {
    return { scope1: 0, scope2: 0, scope3: 0 };
  }
  if (/electric|grid|utility|power|energy bill/.test(c)) {
    return { scope1: 0, scope2: t * 0.92, scope3: t * 0.08 };
  }
  if (/fuel|diesel|petrol|vehicle|transport|fleet|delivery|logistics/.test(c)) {
    return { scope1: t * 0.72, scope2: 0, scope3: t * 0.28 };
  }
  if (/material|supplier|purchase|procurement|raw|inventory/.test(c)) {
    return { scope1: 0, scope2: 0, scope3: t };
  }
  return { scope1: t * 0.34, scope2: t * 0.33, scope3: t * 0.33 };
};

export const countProcessedDocuments = (docs: EvidenceDocument[]) =>
  docs.filter((d) => d.status === 'processed').length;

export const countDocumentsWithCo2Signals = (docs: EvidenceDocument[]) =>
  docs.filter((d) => d.status === 'processed' && toSafeNumber(d.carbonFootprint?.co2Emissions) > 0).length;

export const aggregateUploadedDocumentsForAssessment = (
  rawDocs: EvidenceDocument[],
  organizationName: string
): DocumentAssessmentAggregate | null => {
  const eligible = rawDocs.filter(
    (d) => d.status === 'processed' && toSafeNumber(d.carbonFootprint?.co2Emissions) > 0
  );
  if (eligible.length === 0) {
    return null;
  }

  let scope1 = 0;
  let scope2 = 0;
  let scope3 = 0;
  const vendorMap: Record<string, number> = {};
  const productMap: Record<string, { quantity: number; unit: string; allocatedKg: number }> = {};

  eligible.forEach((doc) => {
    const co2 = toSafeNumber(doc.carbonFootprint?.co2Emissions);
    const breakdown = doc.carbonFootprint?.emissionBreakdown;
    const hasBreakdown =
      toSafeNumber(breakdown?.scope1) + toSafeNumber(breakdown?.scope2) + toSafeNumber(breakdown?.scope3) > 0;
    const category = doc.extractedData?.category || 'general';
    if (hasBreakdown) {
      scope1 += toSafeNumber(breakdown?.scope1);
      scope2 += toSafeNumber(breakdown?.scope2);
      scope3 += toSafeNumber(breakdown?.scope3);
    } else {
      const inferred = inferScopesFromCategory(category, co2);
      scope1 += inferred.scope1;
      scope2 += inferred.scope2;
      scope3 += inferred.scope3;
    }

    const vendorName = doc.extractedData?.vendor?.name?.trim() || 'Unattributed vendor';
    vendorMap[vendorName] = (vendorMap[vendorName] || 0) + co2;

    const items = doc.extractedData?.items;
    const lineTotals = Array.isArray(items)
      ? items.reduce((sum, line) => sum + Math.max(0, toSafeNumber(line.total)), 0)
      : 0;
    if (Array.isArray(items) && lineTotals > 0) {
      items.forEach((line) => {
        const lineTotal = Math.max(0, toSafeNumber(line.total));
        const share = lineTotal / lineTotals;
        const key = line.name?.trim() || 'Unspecified line item';
        if (!productMap[key]) {
          productMap[key] = { quantity: 0, unit: line.unit || 'unit', allocatedKg: 0 };
        }
        productMap[key].quantity += toSafeNumber(line.quantity);
        productMap[key].allocatedKg += co2 * share;
        if (line.unit) {
          productMap[key].unit = line.unit;
        }
      });
    }
  });

  const orgTotal = eligible.reduce((s, d) => s + toSafeNumber(d.carbonFootprint?.co2Emissions), 0);
  const scopeSum = scope1 + scope2 + scope3;
  if (scopeSum > 0 && orgTotal > 0) {
    const scale = orgTotal / scopeSum;
    scope1 *= scale;
    scope2 *= scale;
    scope3 *= scale;
  }
  const totalCo2 = orgTotal;

  const hotspots: DocumentHotspotRow[] = [...eligible]
    .map((doc) => ({
      id: doc.id,
      name: doc.originalName,
      co2: toSafeNumber(doc.carbonFootprint?.co2Emissions),
      category: doc.extractedData?.category || 'general',
      vendor: doc.extractedData?.vendor?.name?.trim() || '—',
      date: doc.extractedData?.date || doc.createdAt
    }))
    .sort((a, b) => b.co2 - a.co2)
    .slice(0, 8);

  const companyRows = [
    { label: organizationName || 'Your organization (document inventory)', totalKg: orgTotal },
    ...Object.entries(vendorMap)
      .map(([label, totalKg]) => ({ label: `Vendor: ${label}`, totalKg }))
      .sort((a, b) => b.totalKg - a.totalKg)
      .slice(0, 6)
  ];

  const productRows = Object.entries(productMap)
    .map(([productName, v]) => ({
      productName,
      quantity: v.quantity,
      unit: v.unit,
      allocatedKg: v.allocatedKg
    }))
    .sort((a, b) => b.allocatedKg - a.allocatedKg)
    .slice(0, 15);

  return {
    totalCo2,
    scope1,
    scope2,
    scope3,
    hotspots,
    companyRows,
    productRows,
    documentCount: eligible.length
  };
};
